// WebAudio manager. Assets generated by forge tools into public/assets/audio.
// Context unlocks on first user gesture (the Play button).

export class AudioMan {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private sfxGain: GainNode | null = null;
  private buffers = new Map<string, AudioBuffer[]>();
  private musicSrc: AudioBufferSourceNode | null = null;
  musicOn = true;
  sfxOn = true;

  /** Call from a user-gesture handler. */
  unlock(): void {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return;
    }
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.9;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = this.musicOn ? 0.35 : 0;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = this.sfxOn ? 1 : 0;
    this.sfxGain.connect(this.master);
  }

  async load(manifest: Record<string, string[]>): Promise<void> {
    if (!this.ctx) return;
    const jobs: Promise<void>[] = [];
    for (const [name, urls] of Object.entries(manifest)) {
      jobs.push((async () => {
        const list: AudioBuffer[] = [];
        for (const u of urls) {
          try {
            const res = await fetch(u);
            if (!res.ok) continue;
            const buf = await this.ctx!.decodeAudioData(await res.arrayBuffer());
            list.push(buf);
          } catch { /* missing asset = silent */ }
        }
        if (list.length) this.buffers.set(name, list);
      })());
    }
    await Promise.all(jobs);
  }

  startMusic(): void {
    if (!this.ctx || this.musicSrc) return;
    const music = this.buffers.get('music');
    if (!music?.length) return;
    this.musicSrc = this.ctx.createBufferSource();
    this.musicSrc.buffer = music[0];
    this.musicSrc.loop = true;
    this.musicSrc.connect(this.musicGain!);
    this.musicSrc.start();
  }

  play(name: string, rate = 1, jitter = 0.06): void {
    if (!this.ctx || !this.sfxOn) return;
    const list = this.buffers.get(name);
    if (!list?.length) return;
    const buf = list[Math.floor(Math.random() * list.length)];
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = rate * (1 + (Math.random() * 2 - 1) * jitter);
    src.connect(this.sfxGain!);
    src.start();
  }

  setMusicOn(on: boolean): void {
    this.musicOn = on;
    if (this.musicGain && this.ctx) {
      this.musicGain.gain.linearRampToValueAtTime(on ? 0.35 : 0, this.ctx.currentTime + 0.2);
    }
  }

  setSfxOn(on: boolean): void {
    this.sfxOn = on;
    if (this.sfxGain && this.ctx) {
      this.sfxGain.gain.linearRampToValueAtTime(on ? 1 : 0, this.ctx.currentTime + 0.1);
    }
  }
}
